無名関数vs関数の上書き
 image.onload = function(){
        drawImage(image,context,canvas);
    };
function drawImage(image, context, canvas) {
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
};
と
 image.onload = drawImage(image,context,canvas);

function drawImage(image, context, canvas) {
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
};
で前者はimageを描画するが後者はしない. 理由がわからなかったのでGPTに聞いてみた. 結果:
最初の例：

```javascript
image.onload = function(){
    drawImage(image, context, canvas);
};

function drawImage(image, context, canvas) {
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
};
```

ここでは、`image.onload`への代入に無名関数（またはアロー関数）を使用しています。この方法から、JavaScriptはこの関数を`onload`イベントが発生したときに実行します。つまり、画像が完全に読み込まれた時点で関数が呼び出されます。

二番目の例：

```javascript
image.onload = drawImage(image, context, canvas);

function drawImage(image, context, canvas) {
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
};
```

ここでは、`drawImage`関数の評価がすぐに実行されます。つまり、`image.onload`には`drawImage`関数の戻り値が代入されます。しかし、この`drawImage`関数には戻り値がありません（undefinedを返します）。そのため、`image.onload`はundefinedになります。これではイベントハンドラとして機能しません。

`drawImage`はイベントが発生するまで待つ必要があるため、関数自体をアサインする必要があります。つまり、関数を呼び出すのではなく、関数自体（または無名関数）を代入するべきです。

そのため、次のように書くべきです：

```javascript
image.onload = function() {
    drawImage(image, context, canvas); 
};
```

あるいは、引数を含まない関数を作り、その関数を代入することもできます：

```javascript
image.onload = drawImage;

function drawImage() {
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
};
```

サンプルコード
以下のコードはsample.txtをshared driveへアップロードする. driveIdを上の説明を参考に書き換えた後sample.txt, credential.jsonを同じディレクトリに置いて実行する. shared driveへファイルをアップロードするにはSupportsAllDrives(true)とする必要があり, ここに辿り着くまでに時間がかかり面倒だった.


Code
package main

import (

    "encoding/json"
    "io/ioutil"
    "log"
    "net/http"
    "os"
    "google.golang.org/api/drive/v3"
    "golang.org/x/oauth2"
    "golang.org/x/oauth2/google"
    "golang.org/x/oauth2/jwt"
)

// ServiceAccount : Use Service account
func ServiceAccount(credentialFile string) *http.Client {
    b, err := ioutil.ReadFile(credentialFile)
    if err != nil {
        log.Fatal(err)
    }
    var c = struct {
        Email      string `json:"client_email"`
        PrivateKey string `json:"private_key"`
    }{}
    json.Unmarshal(b, &c)
    config := &jwt.Config{
        Email:      c.Email,
        PrivateKey: []byte(c.PrivateKey),
        Scopes: []string{
            drive.DriveScope,
        },
        TokenURL: google.JWTTokenURL,
    }
    client := config.Client(oauth2.NoContext)
    return client
}


func main() {


    filePath := "sample.txt"     // file path 
    driveId := "XXX"

    //use survice account
    client := ServiceAccount("credential.json") // Please set the json file of Service account.

    srv, err := drive.New(client)
    if err != nil {
        log.Fatalf("Unable to retrieve drive Client %v", err)
    }

    uploadFile, err := os.Open(filePath)
    if err != nil {
        log.Fatalf("Cannot find such file %v", err)
    }

    folderIdList := [] string{driveId}
    f := &drive.File{Name: filePath, Parents: folderIdList}

    _, err = srv.Files.Create(f).SupportsAllDrives(true).Media(uploadFile).Do()
    if err != nil {
        log.Fatalf("Upload Failed %v", err)
    }

}

terraform側の準備
カタログとnamespaceはterraformで作れる. bigqueryのCREATE TABLEはnamespaceが存在している前提なので, テーブルを作る前にnamespaceを用意しておく必要がある:
resource "google_storage_bucket" "lakehouse" {
  name                        = "my-lakehouse-bucket"
  location                    = "us-central1"
  force_destroy               = true
  uniform_bucket_level_access = true
}

resource "google_biglake_iceberg_catalog" "main" {
  name             = google_storage_bucket.lakehouse.name
  catalog_type     = "CATALOG_TYPE_GCS_BUCKET"
  credential_mode  = "CREDENTIAL_MODE_VENDED_CREDENTIALS"
  primary_location = "us-central1"
}

resource "google_biglake_iceberg_namespace" "gold" {
  catalog      = google_biglake_iceberg_catalog.main.name
  namespace_id = "gold"
}

# vended credentialsではカタログのサービスエージェントが
# 利用者に代わってGCS上のmetadata/dataを読み書きするため, この権限が必要
resource "google_storage_bucket_iam_member" "catalog_agent" {
  bucket = google_storage_bucket.lakehouse.name
  role   = "roles/storage.objectAdmin"
  member = "serviceAccount:${google_biglake_iceberg_catalog.main.biglake_service_account}"
}
最後のIAMを忘れると, テーブル作成時にstorage.objects.create deniedの403で落ちる. vended credentialsモードではクエリエンジンが自分の権限でGCSに書くのではなく, カタログのサービスエージェントが発行する短命のトークンを使ってGCSにアクセスするためである.

